using System.Collections.Generic;

namespace Acme.Catalog;

public sealed class ProductLookup
{
    private readonly Dictionary<string, Product> _bySku;

    public Product Find(string sku)
    {
        _bySku.TryGetValue(sku, out var product);
        return product;
    }

    public string DescribeCategory(Product product)
    {
        return product.Category.Name.ToUpperInvariant();
    }
}

