public Product? Find(string sku)
{
    return _bySku.TryGetValue(sku, out var product) ? product : null;
}

using System.Diagnostics.CodeAnalysis;

public Product Get(string sku)
{
    return _bySku.TryGetValue(sku, out var product)
        ? product
        : throw new KeyNotFoundException(sku);
}

public bool TryGet(string sku, [NotNullWhen(true)] out Product? product)
{
    return _bySku.TryGetValue(sku, out product);
}

public sealed class Product
{
    public required string Sku { get; init; }
    public Category? Category { get; init; }

    [MemberNotNullWhen(true, nameof(Category))]
    public bool HasCategory => Category is not null;
}

public string DescribeCategory(Product product)
{
    return product.HasCategory ? product.Category.Name.ToUpperInvariant() : "UNCATEGORIZED";
}
